<section class="coupon-stats"><article><span class="coupon-stat-icon purple">%</span><div><small>COUPONS CRÉÉS</small><strong><?= count($items) ?></strong><p>Toutes les campagnes</p></div></article><article><span class="coupon-stat-icon green">✓</span><div><small>ACTIFS</small><strong><?= $activeCount ?></strong><p>Utilisables actuellement</p></div></article><article><span class="coupon-stat-icon orange">↗</span><div><small>UTILISATIONS</small><strong><?= $uses ?></strong><p>Commandes remisées</p></div></article></section>

<div class="coupon-layout">
    <form class="panel coupon-creator" method="post" action="/admin/coupons">
