            <div class="coupon-type"><span>Type de remise</span><div><label><input type="radio" name="type" value="percent" checked><span><b>%</b><strong>Pourcentage</strong><small>Ex. 10 % sur le panier</small></span></label><label><input type="radio" name="type" value="fixed"><span><b>F</b><strong>Montant fixe</strong><small>Ex. 5 000 FCFA</small></span></label></div></div>
            <div class="field-grid"><label><span>Valeur de la remise *</span><div class="coupon-value-input"><input type="number" min="0.01" step="0.01" name="value" required placeholder="10"><b data-value-unit>%</b></div></label><label><span>Minimum d’achat</span><div class="coupon-value-input"><input type="number" min="0" name="minimum_amount" value="0"><b>FCFA</b></div><small>0 signifie aucun minimum.</small></label><label><span>Nombre maximal d’utilisations</span><input type="number" min="1" name="usage_limit" placeholder="Illimité"><small>Laissez vide pour un nombre illimité.</small></label></div>
        </section>
        <section class="coupon-period"><div class="section-mini-title"><span>◷</span><div><h3>Période de validité</h3><p>Optionnel — sans date, le coupon reste actif.</p></div></div><div class="field-grid"><label><span>Début</span><input type="datetime-local" name="starts_at"></label><label><span>Expiration</span><input type="datetime-local" name="expires_at"></label></div></section>
