<section class="panel coupon-library"><div class="panel-head"><div><h3>Vos campagnes promotionnelles</h3><p><?= count($items) ?> coupon<?= count($items)>1?'s':'' ?> enregistré<?= count($items)>1?'s':'' ?></p></div><label class="coupon-search"><span>⌕</span><input data-coupon-search placeholder="Rechercher un code..."></label></div><?php if(!$items): ?><div class="coupon-empty"><span>%</span><h3>Aucun coupon pour le moment</h3><p>Créez votre première offre avec le formulaire ci-dessus.</p></div><?php else: ?><div class="coupon-cards"><?php foreach($items as $item): $expired=$item['expires_at']&&strtotime($item['expires_at'])<time();$limit=$item['usage_limit']===null?null:(int)$item['usage_limit'];$progress=$limit?min(100,round((int)$item['used_count']/$limit*100)):0; ?><article data-coupon-row data-search="<?= htmlspecialchars(mb_strtolower($item['code'])) ?>"><div class="coupon-card-code"><span>%</span><div><strong><?= htmlspecialchars($item['code']) ?></strong><small>Créé le <?= date('d/m/Y',strtotime($item['created_at'])) ?></small></div></div><div class="coupon-discount"><small>REMISE</small><strong><?= number_format($item['value'],0,',',' ') ?><?= $item['type']==='percent'?' %':' FCFA' ?></strong><?php if((float)$item['minimum_amount']>0): ?><span>Dès <?= number_format($item['minimum_amount'],0,',',' ') ?> F</span><?php endif ?></div><div class="coupon-usage"><div><span>Utilisations</span><b><?= (int)$item['used_count'] ?> / <?= $limit??'∞' ?></b></div><i><b style="width:<?= $progress ?>%"></b></i></div><div class="coupon-validity"><small>VALIDITÉ</small><strong><?= $item['expires_at']?'Jusqu’au '.date('d/m/Y',strtotime($item['expires_at'])):'Sans expiration' ?></strong></div><span class="coupon-state <?= $item['status']==='active'&&!$expired?'active':'inactive' ?>"><?= $item['status']==='active'&&!$expired?'● Actif':'○ Inactif' ?></span><?php if($item['status']==='active'): ?><form method="post" action="/admin/coupons/supprimer"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="coupon-disable" title="Désactiver">×</button></form><?php endif ?></article><?php endforeach ?></div><?php endif ?></section>

<script>(()=>{const code=document.querySelector('[name="code"]'),value=document.querySelector('[name="value"]'),unit=document.querySelector('[data-value-unit]'),previewCode=document.querySelector('[data-preview-code]'),previewValue=document.querySelector('[data-preview-value]');const sync=()=>{const percent=document.querySelector('[name="type"]:checked').value==='percent';unit.textContent=percent?'%':'FCFA';previewCode.textContent=code.value.trim().toUpperCase()||'BIENVENUE10';previewValue.textContent='−'+(value.value||'10')+(percent?'%':' F')};document.querySelectorAll('[name="type"]').forEach(input=>input.addEventListener('change',sync));code.addEventListener('input',()=>{code.value=code.value.toUpperCase().replace(/[^A-Z0-9_-]/g,'');sync()});value.addEventListener('input',sync);document.querySelector('[data-generate-coupon]').addEventListener('click',()=>{code.value='IFMAP'+Math.random().toString(36).slice(2,7).toUpperCase();sync()});document.querySelector('[data-coupon-search]')?.addEventListener('input',event=>document.querySelectorAll('[data-coupon-row]').forEach(row=>row.hidden=!row.dataset.search.includes(event.target.value.toLocaleLowerCase())));sync()})();</script>

